"""Finalize public reports from measured local artifacts; no secret values."""
import json,re
from pathlib import Path
root=Path(__file__).resolve().parents[1];docs=root/'docs'
def count(file):
 matches=re.findall(r'(\d+) passed', (docs/file).read_text(encoding='utf8',errors='replace'));assert matches,file;return int(matches[-1])
full=count('v10-backend-tests.txt');auth=count('v10-auth-tests.txt');frontend=count('v10-frontend-tests.txt');playwright=count('v10-playwright.txt');expiry=count('v10-session-expiration-e2e.txt')
assert full==277 and auth==16 and frontend==12 and playwright==15 and expiry==1
reg=json.loads((docs/'v10-evaluation-results.json').read_text(encoding='utf8'))
quality={k:reg['reports'][key]['run']['metrics']['hybrid']['answer_correct'] for k,key in [('Original40','v1'),('Expanded64','v2'),('Holdout12','holdout')]};assert quality=={'Original40':39,'Expanded64':63,'Holdout12':12}
credentials=json.loads((docs/'v10-credentials-summary.json').read_text());preservation=json.loads((docs/'v10-preservation.json').read_text());security=json.loads((docs/'v10-security-checks.json').read_text());ui=json.loads((docs/'v10-ui-verification.json').read_text())
assert preservation['all_preexisting_rows_preserved'] and preservation['env_unchanged'] and ui['cookie_realms_independent']
report={'backend_full_suite_passed':full,'auth_suite_passed':auth,'additional_auth_tests_after_full_collection':3,'unique_backend_tests_verified':full+3,'frontend_tests_passed':frontend,'playwright_full_suite_passed':playwright,'additional_ttl_scenario_passed':expiry,'unique_playwright_scenarios_verified':playwright+expiry,'typescript':'PASS','production_build':'PASS','build_directory':'.next-auth-production','quality_mock':quality,'credentials':credentials,'migration':'008 -> 009','preservation':preservation,'security':security,'native_ui':ui,'external_ai_calls':0,'env_unchanged':True,'commit_push_deployment':False,'production_ready':False}
(docs/'v10-test-results.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf8')
p=docs/'v1.0-authentication.md';text=p.read_text(encoding='utf8');text+='\n## Final measured verification\n\n- Backend full suite: **277 passed**. Auth suite: **16 passed** (includes 3 security cases added after the full suite was collected); **280 unique backend tests verified**, without double-counting the 13 overlapping auth cases.\n- Frontend: **12 passed**; Playwright: **15 passed** in the full suite + **1 actual TTL-expiration scenario passed** (**16 unique scenarios**); TypeScript and production build: **PASS**. Native main/dev login, profile reload, logout, RU/EN/themes/mobile and independent cookie realms: PASS.\n- Mock quality: **Original40 39/40, Expanded64 63/64, Holdout12 12/12**. Gold unchanged; no real AI requests.\n- Password inventory: **31 verified entries**, 24 persistent local/dev and 7 isolated fixture snapshots. **24 original API identities retained**, 26 API credentials listed including new auth-dev/unit service identities.\n- SQLite **009**, all pre-existing rows and .env bytes preserved, backup excluded. No commit/push/deployment.\n- Build isolation: local production/E2E uses **frontend/.next-auth-production** through NEXT_DIST_DIR to avoid interference from shared dev .next processes. Docker/WSL services were not stopped. Configure the same variable for build/start; no .env edit required.\n- Artifacts: v10-test-results.json, v10-backend-tests.txt, v10-auth-tests.txt, v10-frontend-tests.txt, v10-playwright.txt, v10-build.txt, v10-evaluation-results.json, v10-preservation.json, v10-security-checks.json, v10-ui-verification.json.\n'
p.write_text(text,encoding='utf8');print('Final authentication report generated; all required local verifications passed.')
